import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ChunkReverserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<String> listOf(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    public static void main(String[] args) {
        try {
            check("chunks of 2 over 5 items", "[e, c, d, a, b]",
                    ChunkReverser.reverseChunks(listOf("a", "b", "c", "d", "e"), 2).toString());
            check("chunks of 2 dividing evenly", "[3, 4, 1, 2]",
                    ChunkReverser.reverseChunks(listOf("1", "2", "3", "4"), 2).toString());
            check("chunk size of 1 is a plain reverse", "[e, d, c, b, a]",
                    ChunkReverser.reverseChunks(listOf("a", "b", "c", "d", "e"), 1).toString());
            check("chunk size larger than the list", "[a, b, c]",
                    ChunkReverser.reverseChunks(listOf("a", "b", "c"), 9).toString());
            check("chunk size of 0 copies the list", "[a, b, c]",
                    ChunkReverser.reverseChunks(listOf("a", "b", "c"), 0).toString());
            check("empty list", "[]", ChunkReverser.reverseChunks(listOf(), 3).toString());
            check("chunks of 3 over 7 items", "[7, 4, 5, 6, 1, 2, 3]",
                    ChunkReverser.reverseChunks(listOf("1", "2", "3", "4", "5", "6", "7"), 3).toString());

            List<String> source = listOf("a", "b", "c");
            ChunkReverser.reverseChunks(source, 2);
            check("input list untouched", "[a, b, c]", source.toString());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

