import java.util.ArrayList;
import java.util.List;

public class ChunkReverser {

    public static List<String> reverseChunks(List<String> items, int chunkSize) {
        List<String> result = new ArrayList<>();
        if (chunkSize < 1) {
            result.addAll(items);
            return result;
        }
        int lastStart = 0;
        while (lastStart + chunkSize < items.size()) {
            lastStart += chunkSize;
        }
        for (int start = lastStart; start >= 0; start -= chunkSize) {
            int end = Math.min(start + chunkSize, items.size());
            for (int i = start; i < end; i++) {
                result.add(items.get(i));
            }
        }
        return result;
    }
}
